from typing import Any, Optional, Type, Union, Dict, List
from functools import wraps

# Descriptor para validar tipos
class TypedDescriptor:
    """
    Descriptor que valida el tipo de un atributo al asignarle un valor.

    Args:
        expected_type: Tipo esperado para el atributo
        name: Nombre del atributo (usado para mensajes de error)
    """

    def __init__(self, expected_type: Type, name: str = ""):
        self.expected_type = expected_type
        self.name = name
        self.private_name = f"_{name}"

    def __get__(self, obj: Any, objtype: Optional[Type] = None) -> Any:
        if obj is None:
            return self
        return getattr(obj, self.private_name, None)

    def __set__(self, obj: Any, value: Any) -> None:
        if not isinstance(value, self.expected_type):
            raise TypeError(f"{self.name} debe ser de tipo {self.expected_type.__name__}, "
                          f"pero se recibió {type(value).__name__}")
        setattr(obj, self.private_name, value)

# Descriptor para atributos con valor por defecto
class DefaultDescriptor:
    """
    Descriptor que permite valores por defecto y validación de rangos.

    Args:
        default: Valor por defecto
        min_value: Valor mínimo permitido (opcional)
        max_value: Valor máximo permitido (opcional)
    """

    def __init__(self, default: Any, min_value: Optional[Union[int, float]] = None, 
                 max_value: Optional[Union[int, float]] = None):
        self.default = default
        self.min_value = min_value
        self.max_value = max_value
        self.name = ""

    def __get__(self, obj: Any, objtype: Optional[Type] = None) -> Any:
        if obj is None:
            return self
        return getattr(obj, f"_{self.name}", self.default)

    def __set__(self, obj: Any, value: Any) -> None:
        # Validar rango
        if self.min_value is not None and value < self.min_value:
            raise ValueError(f"{self.name} debe ser mayor o igual a {self.min_value}")
        if self.max_value is not None and value > self.max_value:
            raise ValueError(f"{self.name} debe ser menor o igual a {self.max_value}")

        setattr(obj, f"_{self.name}", value)

# Metaclase que registra métodos y atributos
class RegistryMeta(type):
    """
    Metaclase que registra automáticamente los métodos y atributos definidos en una clase.

    Atributos:
        _registry: Diccionario que almacena la información de registro
    """

    def __new__(mcs, name: str, bases: tuple, namespace: Dict[str, Any], **kwargs) -> Type:
        # Crear la nueva clase
        cls = super().__new__(mcs, name, bases, namespace)

        # Inicializar el registro
        cls._registry = {
            'attributes': [],
            'methods': [],
            'properties': []
        }

        # Registrar atributos y métodos
        for key, value in namespace.items():
            if not key.startswith('_'):
                if callable(value):
                    cls._registry['methods'].append(key)
                elif isinstance(value, (TypedDescriptor, DefaultDescriptor)):
                    cls._registry['attributes'].append(key)
                else:
                    # Atributos regulares
                    cls._registry['attributes'].append(key)

        return cls

