# Singleton Pattern
class SingletonMeta(type):
    """
    Metaclase para implementar el patrón Singleton.
    Garantiza que solo exista una instancia de la clase.
    """
    _instances: Dict[type, Any] = {}

    def __call__(cls, *args, **kwargs):
        if cls not in cls._instances:
            cls._instances[cls] = super().__call__(*args, **kwargs)
        return cls._instances[cls]

class DatabaseConnection(metaclass=SingletonMeta):
    """
    Ejemplo de clase Singleton que representa una conexión a base de datos.
    """
    def __init__(self) -> None:
        self.connection_string = "postgresql://localhost:5432/mydb"
        self.connected = False

    def connect(self) -> None:
        """Conecta a la base de datos."""
        self.connected = True

    def disconnect(self) -> None:
        """Desconecta de la base de datos."""
        self.connected = False

    def execute_query(self, query: str) -> str:
        """Ejecuta una consulta SQL."""
        if not self.connected:
            raise RuntimeError("No hay conexión a la base de datos")
        return f"Resultado de la consulta: {query}"

# Factory Pattern
class PaymentProcessor(ABC):
    """
    Clase abstracta para procesadores de pago.
    """
    @abstractmethod
    def process_payment(self, amount: float) -> bool:
        """Procesa un pago."""
        pass

class CreditCardProcessor(PaymentProcessor):
    """Procesador de pago con tarjeta de crédito."""
    def process_payment(self, amount: float) -> bool:
        return amount > 0

class PayPalProcessor(PaymentProcessor):
    """Procesador de pago con PayPal."""
    def process_payment(self, amount: float) -> bool:
        return amount > 0

class PaymentProcessorFactory:
    """
    Factoría para crear procesadores de pago según el tipo especificado.
    """
    @staticmethod
    def create_processor(processor_type: str) -> PaymentProcessor:
        """
        Crea un procesador de pago según el tipo especificado.

        Args:
            processor_type: Tipo de procesador ('credit_card' o 'paypal')

        Returns:
            Instancia de PaymentProcessor

        Raises:
            ValueError: Si el tipo de procesador no es válido
        """
        if processor_type == "credit_card":
            return CreditCardProcessor()
        elif processor_type == "paypal":
            return PayPalProcessor()
        else:
            raise ValueError(f"Tipo de procesador no soportado: {processor_type}")

# Observer Pattern
class Observer(ABC):
    """
    Interfaz para observadores.
    """
    @abstractmethod
    def update(self, subject: 'Subject') -> None:
        """Método llamado cuando el sujeto cambia."""
        pass

class Subject(ABC):
    """
    Clase base para sujetos observables.
    """
    def __init__(self) -> None:
        self._observers: List[Observer] = []

    def attach(self, observer: Observer) -> None:
        """Añade un observador."""
        if observer not in self._observers:
            self._observers.append(observer)

    def detach(self, observer: Observer) -> None:
        """Elimina un observador."""
        if observer in self._observers:
            self._observers.remove(observer)

    def notify(self) -> None:
        """Notifica a todos los observadores."""
        for observer in self._observers:
            observer.update(self)

class Order(Subject):
    """
    Clase que representa un pedido y notifica cambios a sus observadores.
    """
    def __init__(self, order_id: str) -> None:
        super().__init__()
        self.order_id = order_id
        self.status = "pending"

    def set_status(self, status: str) -> None:
        """Establece el estado del pedido."""
        self.status = status
        self.notify()

