def frecuencias(lista: list) -> dict:
    """
    Calcula la frecuencia de cada elemento en una lista.

    Args:
        lista: Lista de elementos

    Returns:
        Diccionario con elementos como claves y sus frecuencias como valores

    Example:
        >>> frecuencias(['a', 'b', 'a', 'c', 'b', 'a'])
        {'a': 3, 'b': 2, 'c': 1}
    """
    if not lista:
        return {}
    frec = {}
    for item in lista:
        frec[item] = frec.get(item, 0) + 1
    return frec


def invertir(dic: dict) -> dict:
    """
    Invierte un diccionario intercambiando claves y valores.

    Args:
        dic: Diccionario a invertir

    Returns:
        Nuevo diccionario con claves y valores intercambiados

    Example:
        >>> invertir({'a': 1, 'b': 2, 'c': 3})
        {1: 'a', 2: 'b', 3: 'c'}
    """
    if not dic:
        return {}
    # Maneja el caso de valores no hashables
    try:
        return {v: k for k, v in dic.items()}
    except TypeError:
        return {v: k for k, v in dic.items() if isinstance(v, (int, str, float, bool))}


def merge(dic1: dict, dic2: dict) -> dict:
    """
    Fusiona dos diccionarios, con valores de dic2 sobrescribiendo los de dic1.

    Args:
        dic1: Primer diccionario
        dic2: Segundo diccionario

    Returns:
        Nuevo diccionario fusionado

    Example:
        >>> merge({'a': 1, 'b': 2}, {'b': 3, 'c': 4})
        {'a': 1, 'b': 3, 'c': 4}
    """
    if not isinstance(dic1, dict) or not isinstance(dic2, dict):
        raise TypeError("Ambos argumentos deben ser diccionarios")
    result = dic1.copy()
    result.update(dic2)
    return result


def filtrar_por_valor(dic: dict, valor) -> dict:
    """
    Filtra un diccionario manteniendo solo las entradas con un valor específico.

    Args:
        dic: Diccionario a filtrar
        valor: Valor a filtrar

    Returns:
        Nuevo diccionario con entradas que tienen el valor especificado

    Example:
        >>> filtrar_por_valor({'a': 1, 'b': 2, 'c': 1}, 1)
        {'a': 1, 'c': 1}
    """
    if not isinstance(dic, dict):
        raise TypeError("El primer argumento debe ser un diccionario")
    return {k: v for k, v in dic.items() if v == valor}

