# Implementación simplificada de attrs
class attr:
    """Decorador para simular attrs."""
    def __init__(self, validator: Optional[Callable] = None, converter: Optional[Callable] = None):
        self.validator = validator
        self.converter = converter

    def __call__(self, func):
        return func

def define_attrs(cls):
    """Decorador para definir atributos con validación y conversión."""
    # Guardar métodos originales
    original_init = getattr(cls, '__init__', None)

    @wraps(original_init)
    def __init__(self, *args, **kwargs):
        # Obtener parámetros del constructor
        sig = inspect.signature(original_init)
        bound_args = sig.bind(self, *args, **kwargs)
        bound_args.apply_defaults()

        # Aplicar conversores y validadores
        for attr_name, value in bound_args.arguments.items():
            if attr_name == 'self':
                continue
            attr_def = getattr(cls, attr_name, None)
            if isinstance(attr_def, attr):
                if attr_def.converter:
                    try:
                        value = attr_def.converter(value)
                    except Exception as e:
                        raise ValueError(f"Error al convertir {attr_name}: {e}")
                if attr_def.validator:
                    try:
                        attr_def.validator(value)
                    except Exception as e:
                        raise ValueError(f"Error en validación de {attr_name}: {e}")
            setattr(self, attr_name, value)

        if original_init:
            original_init(self, *args, **kwargs)

    cls.__init__ = __init__
    return cls

# Validadores
def validate_email(email: str):
    """Valida que el email contenga @."""
    if not isinstance(email, str) or "@" not in email:
        raise ValueError("El correo debe contener '@'")

def validate_age(age: int):
    """Valida que la edad sea positiva."""
    if not isinstance(age, int) or age < 0:
        raise ValueError("La edad debe ser un entero no negativo")

def validate_name(name: str):
    """Valida que el nombre no esté vacío."""
    if not isinstance(name, str) or not name.strip():
        raise ValueError("El nombre debe ser una cadena no vacía")

def convert_to_str(value: Any) -> str:
    """Convierte un valor a string."""
    return str(value)

def convert_to_int(value: Any) -> int:
    """Convierte un valor a entero."""
    try:
        return int(value)
    except (ValueError, TypeError):
        raise ValueError(f"No se puede convertir {value} a entero")

@define_attrs
class PersonAttrs:
    """
    Ejemplo de clase con attrs simulados.

    Atributos:
        name: Nombre de la persona (str)
        age: Edad de la persona (int)
        email: Correo electrónico (str)
    """
    name: str = attr(validator=validate_name, converter=convert_to_str)
    age: int = attr(validator=validate_age, converter=convert_to_int)
    email: str = attr(validator=validate_email, converter=convert_to_str)

    def __init__(self, name: str, age: int, email: str):
        self.name = name
        self.age = age
        self.email = email

    def __str__(self):
        return f"PersonAttrs(name='{self.name}', age={self.age}, email='{self.email}')"

