@dataclass
class Field:
    """Campo de modelo con sus propiedades."""
    name: str
    field_type: Type
    nullable: bool = False
    default: Any = None
    primary_key: bool = False
    unique: bool = False

class QuerySet:
    """Representa un conjunto de resultados de una consulta."""

    def __init__(self, model_class: Type['Model'], db_connection: sqlite3.Connection):
        self.model_class = model_class
        self.db_connection = db_connection
        self._where_conditions = []
        self._order_by = []
        self._limit = None
        self._offset = None

    def filter(self, **kwargs) -> 'QuerySet':
        """Añade condiciones de filtro a la consulta."""
        for field_name, value in kwargs.items():
            if field_name in self.model_class._fields:
                self._where_conditions.append((field_name, value))
            else:
                raise ValueError(f"Campo '{field_name}' no existe en {self.model_class.__name__}")
        return self

    def order_by(self, *fields: str) -> 'QuerySet':
        """Ordena los resultados por los campos especificados."""
        self._order_by = list(fields)
        return self

    def limit(self, limit: int) -> 'QuerySet':
        """Limita el número de resultados."""
        self._limit = limit
        return self

    def offset(self, offset: int) -> 'QuerySet':
        """Salta un número específico de resultados."""
        self._offset = offset
        return self

    def _build_where_clause(self) -> tuple:
        """Construye la cláusula WHERE."""
        if not self._where_conditions:
            return "", []

        conditions = []
        params = []
        for field_name, value in self._where_conditions:
            if value is None:
                conditions.append(f"{field_name} IS NULL")
            else:
                conditions.append(f"{field_name} = ?")
                params.append(value)

        return " AND ".join(conditions), params

    def _build_order_by_clause(self) -> str:
        """Construye la cláusula ORDER BY."""
        if not self._order_by:
            return ""
        return " ORDER BY " + ", ".join(self._order_by)

    def _build_limit_clause(self) -> str:
        """Construye la cláusula LIMIT."""
        if self._limit is None:
            return ""
        limit_clause = f" LIMIT {self._limit}"
        if self._offset is not None:
            limit_clause += f" OFFSET {self._offset}"
        return limit_clause

    def all(self) -> List['Model']:
        """Obtiene todos los registros que coinciden con los filtros."""
        where_clause, params = self._build_where_clause()
        order_by_clause = self._build_order_by_clause()
        limit_clause = self._build_limit_clause()

        query = f"SELECT * FROM {self.model_class._table_name}"
        if where_clause:
            query += f" WHERE {where_clause}"
        query += order_by_clause + limit_clause

        cursor = self.db_connection.execute(query, params)
        columns = [description[0] for description in cursor.description]
        results = []
        for row in cursor.fetchall():
            instance = self.model_class()
            for i, column in enumerate(columns):
                setattr(instance, column, row[i])
            results.append(instance)
        return results

    def first(self) -> Optional['Model']:
        """Obtiene el primer registro que coincida con los filtros."""
        return self.limit(1).all()[0] if self.all() else None

    def count(self) -> int:
        """Cuenta el número de registros que coinciden con los filtros."""
        where_clause, params = self._build_where_clause()
        query = f"SELECT COUNT(*) FROM {self.model_class._table_name}"
        if where_clause:
            query += f" WHERE {where_clause}"

        cursor = self.db_connection.execute(query, params)
        return cursor.fetchone()[0]

class Manager:
    """Gestiona las operaciones del modelo."""

    def __init__(self, model_class: Type['Model'], db_path: str):
        self.model_class = model_class
        self.db_path = db_path
        self.db_connection = sqlite3.connect(db_path, check_same_thread=False)
        self._create_table_if_not_exists()

    def _create_table_if_not_exists(self):
        """Crea la tabla si no existe."""
        fields_sql = []
        primary_key_fields = []

        for field in self.model_class._fields.values():
            field_sql = f"{field.name} {self._get_sql_type(field.field_type)}"
            if field.primary_key:
                primary_key_fields.append(field.name)
                field_sql += " PRIMARY KEY"
            if field.nullable:
                field_sql += " NULL"
            else:
                field_sql += " NOT NULL"
            if field.default is not None and not field.primary_key:
                field_sql += f" DEFAULT {self._get_default_value(field.default)}"
            fields_sql.append(field_sql)

        if primary_key_fields:
            fields_sql.append(f"PRIMARY KEY ({', '.join(primary_key_fields)})")

        create_table_sql = f"""
            CREATE TABLE IF NOT EXISTS {self.model_class._table_name} (
                {', '.join(fields_sql)}
            )
        """
        self.db_connection.execute(create_table_sql)
        self.db_connection.commit()

    def _get_sql_type(self, field_type: Type) -> str:
        """Obtiene el tipo SQL correspondiente al tipo Python."""
        type_map = {
            str: "TEXT",
            int: "INTEGER",
            float: "REAL",
            bool: "INTEGER",
            datetime: "TEXT"
        }
        return type_map.get(field_type, "TEXT")

    def _get_default_value(self, default_value: Any) -> str:
        """Obtiene el valor predeterminado formateado para SQL."""
        if isinstance(default_value, str):
            return f"'{default_value}'"
        elif isinstance(default_value, bool):
            return "1" if default_value else "0"
        else:
            return str(default_value)

    def get_queryset(self) -> QuerySet:
        """Obtiene un QuerySet para realizar consultas."""
        return QuerySet(self.model_class, self.db_connection)

