from functools import wraps

class Descriptor:
    """Descriptor base que permite interceptar acceso a atributos."""

    def __init__(self, name: str):
        self.name = name
        self.value = None

    def __get__(self, obj: Any, objtype: Optional[Type] = None) -> Any:
        if obj is None:
            return self
        return getattr(obj, f'_{self.name}', None)

    def __set__(self, obj: Any, value: Any) -> None:
        setattr(obj, f'_{self.name}', value)

    def __delete__(self, obj: Any) -> None:
        if hasattr(obj, f'_{self.name}'):
            delattr(obj, f'_{self.name}')

class ValidatedDescriptor(Descriptor):
    """Descriptor que valida los valores asignados."""

    def __init__(self, name: str, validator=None):
        super().__init__(name)
        self.validator = validator

    def __set__(self, obj: Any, value: Any) -> None:
        if self.validator and not self.validator(value):
            raise ValueError(f"Valor inválido para {self.name}: {value}")
        super().__set__(obj, value)

class PositiveNumber(ValidatedDescriptor):
    """Descriptor para números positivos."""

    def __init__(self, name: str):
        super().__init__(name, lambda x: isinstance(x, (int, float)) and x > 0)

class StringDescriptor(ValidatedDescriptor):
    """Descriptor para cadenas de texto."""

    def __init__(self, name: str):
        super().__init__(name, lambda x: isinstance(x, str) and len(x) > 0)

class MetaClass(type):
    """Metaclase que registra automáticamente los descriptores en una clase."""

    def __new__(mcs, name: str, bases: tuple, namespace: Dict[str, Any]) -> Type:
        # Recoge todos los descriptores definidos en la clase
        descriptors = {}
        for key, value in list(namespace.items()):
            if isinstance(value, Descriptor):
                descriptors[key] = value

        # Añade un método para obtener los descriptores
        namespace['_descriptors'] = descriptors

        # Crea la clase con la metaclase
        cls = super().__new__(mcs, name, bases, namespace)

        # Registra los descriptores en la clase
        cls._registered_descriptors = descriptors
        return cls

class Model(metaclass=MetaClass):
    """Clase base que utiliza metaclases y descriptores."""

    def __init__(self, **kwargs):
        # Asigna valores usando los descriptores
        for key, value in kwargs.items():
            if hasattr(self, key) and isinstance(getattr(type(self), key), Descriptor):
                setattr(self, key, value)
            else:
                setattr(self, key, value)

    def __repr__(self) -> str:
        attrs = []
        for key, descriptor in self._registered_descriptors.items():
            value = getattr(self, key, None)
            if value is not None:
                attrs.append(f"{key}={value!r}")
        return f"{self.__class__.__name__}({', '.join(attrs)})"

    def to_dict(self) -> Dict[str, Any]:
        """Convierte el objeto a un diccionario usando los descriptores."""
        result = {}
        for key, descriptor in self._registered_descriptors.items():
            value = getattr(self, key, None)
            if value is not None:
                result[key] = value
        return result

class User(Model):
    """Ejemplo de clase que hereda de Model y usa descriptores."""

    name = StringDescriptor('name')
    age = PositiveNumber('age')
    email = StringDescriptor('email')

class Product(Model):
    """Otro ejemplo de clase con descriptores."""

    name = StringDescriptor('name')
    price = PositiveNumber('price')
    quantity = PositiveNumber('quantity')

