from abc import ABC, abstractmethod
from typing import Any, Dict, List, Optional, Type, TypeVar

# Singleton Pattern
class SingletonMeta(type):
    """
    Metaclase para implementar el patrón Singleton.
    Garantiza que solo exista una instancia de la clase.
    """
    _instances: Dict[Type, Any] = {}

    def __call__(cls, *args, **kwargs):
        if cls not in cls._instances:
            cls._instances[cls] = super().__call__(*args, **kwargs)
        return cls._instances[cls]

class DatabaseConnection(metaclass=SingletonMeta):
    """
    Ejemplo de clase Singleton que representa una conexión a base de datos.
    """
    def __init__(self) -> None:
        self.connection_string = "postgresql://localhost:5432/mydb"
        self.is_connected = False

    def connect(self) -> None:
        """Establece la conexión a la base de datos."""
        self.is_connected = True

    def disconnect(self) -> None:
        """Cierra la conexión a la base de datos."""
        self.is_connected = False

    def execute_query(self, query: str) -> str:
        """Ejecuta una consulta SQL."""
        if not self.is_connected:
            raise RuntimeError("No hay conexión activa a la base de datos")
        return f"Resultado de consulta: {query}"

# Factory Pattern
T = TypeVar('T', bound='Shape')

class Shape(ABC):
    """
    Clase abstracta base para formas geométricas.
    """
    @abstractmethod
    def area(self) -> float:
        """Calcula el área de la forma."""
        pass

class Circle(Shape):
    """Representa un círculo."""
    def __init__(self, radius: float) -> None:
        if radius < 0:
            raise ValueError("El radio no puede ser negativo")
        self.radius = radius

    def area(self) -> float:
        return 3.14159 * self.radius ** 2

class Rectangle(Shape):
    """Representa un rectángulo."""
    def __init__(self, width: float, height: float) -> None:
        if width < 0 or height < 0:
            raise ValueError("Las dimensiones no pueden ser negativas")
        self.width = width
        self.height = height

    def area(self) -> float:
        return self.width * self.height

class Triangle(Shape):
    """Representa un triángulo."""
    def __init__(self, base: float, height: float) -> None:
        if base < 0 or height < 0:
            raise ValueError("Las dimensiones no pueden ser negativas")
        self.base = base
        self.height = height

    def area(self) -> float:
        return 0.5 * self.base * self.height

class ShapeFactory:
    """
    Fábrica para crear instancias de formas geométricas.
    """
    @staticmethod
    def create_shape(shape_type: str, **kwargs) -> Shape:
        """
        Crea una instancia de una forma geométrica según el tipo especificado.

        Args:
            shape_type: Tipo de forma ("circle", "rectangle", "triangle")
            **kwargs: Parámetros específicos de cada forma

        Returns:
            Instancia de la forma correspondiente

        Raises:
            ValueError: Si el tipo de forma no es válido
        """
        if shape_type == "circle":
            return Circle(**kwargs)
        elif shape_type == "rectangle":
            return Rectangle(**kwargs)
        elif shape_type == "triangle":
            return Triangle(**kwargs)
        else:
            raise ValueError(f"Tipo de forma no soportado: {shape_type}")

# Observer Pattern
class Observer(ABC):
    """
    Interfaz para observadores.
    """
    @abstractmethod
    def update(self, message: str) -> None:
        """Método llamado cuando el sujeto cambia."""
        pass

class Subject:
    """
    Clase base para sujetos observables.
    """
    def __init__(self) -> None:
        self._observers: List[Observer] = []

    def attach(self, observer: Observer) -> None:
        """Agrega un observador."""
        if observer not in self._observers:
            self._observers.append(observer)

    def detach(self, observer: Observer) -> None:
        """Elimina un observador."""
        if observer in self._observers:
            self._observers.remove(observer)

    def notify(self, message: str) -> None:
        """Notifica a todos los observadores."""
        for observer in self._observers:
            observer.update(message)

