from typing import Optional, List, Any, Iterator
from collections import deque

# Linked List Implementation
class ListNode:
    """Node for a singly linked list."""
    def __init__(self, val: int = 0, next: Optional['ListNode'] = None):
        self.val = val
        self.next = next

class LinkedList:
    """Singly linked list implementation."""
    def __init__(self):
        self.head: Optional[ListNode] = None
        self.size = 0

    def append(self, val: int) -> None:
        """Add a new node with value at the end of the list."""
        new_node = ListNode(val)
        if not self.head:
            self.head = new_node
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = new_node
        self.size += 1

    def prepend(self, val: int) -> None:
        """Add a new node with value at the beginning of the list."""
        new_node = ListNode(val, self.head)
        self.head = new_node
        self.size += 1

    def delete(self, val: int) -> bool:
        """Delete the first occurrence of a value. Return True if deleted."""
        if not self.head:
            return False

        if self.head.val == val:
            self.head = self.head.next
            self.size -= 1
            return True

        current = self.head
        while current.next:
            if current.next.val == val:
                current.next = current.next.next
                self.size -= 1
                return True
            current = current.next
        return False

    def find(self, val: int) -> Optional[ListNode]:
        """Find and return the first node with the given value."""
        current = self.head
        while current:
            if current.val == val:
                return current
            current = current.next
        return None

    def to_list(self) -> List[int]:
        """Convert the linked list to a Python list."""
        result = []
        current = self.head
        while current:
            result.append(current.val)
            current = current.next
        return result

    def __len__(self) -> int:
        return self.size

    def __iter__(self) -> Iterator[int]:
        current = self.head
        while current:
            yield current.val
            current = current.next

# Binary Search Tree Implementation
class TreeNode:
    """Node for a binary search tree."""
    def __init__(self, val: int = 0, left: Optional['TreeNode'] = None, right: Optional['TreeNode'] = None):
        self.val = val
        self.left = left
        self.right = right

class BST:
    """Binary search tree implementation."""
    def __init__(self):
        self.root: Optional[TreeNode] = None

    def insert(self, val: int) -> None:
        """Insert a value into the BST."""
        self.root = self._insert_recursive(self.root, val)

    def _insert_recursive(self, node: Optional[TreeNode], val: int) -> TreeNode:
        if not node:
            return TreeNode(val)
        if val < node.val:
            node.left = self._insert_recursive(node.left, val)
        elif val > node.val:
            node.right = self._insert_recursive(node.right, val)
        return node

    def search(self, val: int) -> bool:
        """Search for a value in the BST."""
        return self._search_recursive(self.root, val)

    def _search_recursive(self, node: Optional[TreeNode], val: int) -> bool:
        if not node:
            return False
        if node.val == val:
            return True
        if val < node.val:
            return self._search_recursive(node.left, val)
        else:
            return self._search_recursive(node.right, val)

    def delete(self, val: int) -> bool:
        """Delete a value from the BST. Return True if deleted."""
        self.root, deleted = self._delete_recursive(self.root, val)
        return deleted

    def _delete_recursive(self, node: Optional[TreeNode], val: int) -> tuple[Optional[TreeNode], bool]:
        if not node:
            return None, False

        if val < node.val:
            node.left, deleted = self._delete_recursive(node.left, val)
        elif val > node.val:
            node.right, deleted = self._delete_recursive(node.right, val)
        else:
            # Node to delete found
            if not node.left:
                return node.right, True
            elif not node.right:
                return node.left, True

            # Node with two children: get the inorder successor (smallest in right subtree)
            min_node = self._find_min(node.right)
            node.val = min_node.val
            node.right, _ = self._delete_recursive(node.right, min_node.val)
            return node, True
        return node, False

    def _find_min(self, node: TreeNode) -> TreeNode:
        """Find the minimum value node in a subtree."""
        while node.left:
            node = node.left
        return node

    def inorder_traversal(self) -> List[int]:
        """Return inorder traversal of the BST."""
        result = []
        self._inorder_recursive(self.root, result)
        return result

    def _inorder_recursive(self, node: Optional[TreeNode], result: List[int]) -> None:
        if node:
            self._inorder_recursive(node.left, result)
            result.append(node.val)
            self._inorder_recursive(node.right, result)

    def preorder_traversal(self) -> List[int]:
        """Return preorder traversal of the BST."""
        result = []
        self._preorder_recursive(self.root, result)
        return result

    def _preorder_recursive(self, node: Optional[TreeNode], result: List[int]) -> None:
        if node:
            result.append(node.val)
            self._preorder_recursive(node.left, result)
            self._preorder_recursive(node.right, result)

# Heap Implementation (Min-Heap)
class MinHeap:
    """Min-heap implementation."""
    def __init__(self):
        self.heap: List[int] = []

    def push(self, val: int) -> None:
        """Add a value to the heap."""
        self.heap.append(val)
        self._heapify_up(len(self.heap) - 1)

    def pop(self) -> int:
        """Remove and return the minimum value from the heap."""
        if not self.heap:
            raise IndexError("pop from empty heap")

        if len(self.heap) == 1:
            return

