class PaymentStrategy(ABC):
    """
    Estrategia abstracta para pagos.
    """
    @abstractmethod
    def pay(self, amount: float) -> str:
        """Realiza el pago."""

class CreditCardPayment(PaymentStrategy):
    """Estrategia de pago con tarjeta de crédito."""
    def pay(self, amount: float) -> str:
        return f"Pagado ${amount:.2f} con tarjeta de crédito"

class PayPalPayment(PaymentStrategy):
    """Estrategia de pago con PayPal."""
    def pay(self, amount: float) -> str:
        return f"Pagado ${amount:.2f} con PayPal"

class CashPayment(PaymentStrategy):
    """Estrategia de pago en efectivo."""
    def pay(self, amount: float) -> str:
        return f"Pagado ${amount:.2f} en efectivo"

class PaymentContext:
    """
    Contexto que utiliza una estrategia de pago.
    """
    def __init__(self, strategy: PaymentStrategy):
        self._strategy = strategy

    @property
    def strategy(self) -> PaymentStrategy:
        return self._strategy

    @strategy.setter
    def strategy(self, strategy: PaymentStrategy) -> None:
        self._strategy = strategy

    def execute_payment(self, amount: float) -> str:
        """Ejecuta el pago usando la estrategia actual."""
        return self._strategy.pay(amount)

# Ejemplo de uso completo
def main():
    # Singleton
    print("=== Singleton Pattern ===")
    db1 = DatabaseConnection()
    db2 = DatabaseConnection()
    print(f"Misma instancia: {db1 is db2}")
    db1.connect()
    print(f"Conectado: {db1.is_connected}")
    print(db1.execute_query("SELECT * FROM users"))

    # Factory
    print("\n=== Factory Pattern ===")
    dog = AnimalFactory.create_animal('dog')
    cat = AnimalFactory.create_animal('cat')
    bird = AnimalFactory.create_animal('bird')
    print(f"Perro: {dog.make_sound()}")
    print(f"Gato: {cat.make_sound()}")
    print(f"Pájaro: {bird.make_sound()}")

    # Registrar nuevo animal
    class Fish(Animal):
        def make_sound(self) -> str:
            return "Glup glup"

    AnimalFactory.register_animal('fish', Fish)
    fish = AnimalFactory.create_animal('fish')
    print(f"Pez: {fish.make_sound()}")

    # Observer
    print("\n=== Observer Pattern ===")
    publisher = NewsPublisher()
    subscriber1 = NewsSubscriber("Juan")
    subscriber2 = NewsSubscriber("María")

    publisher.attach(subscriber1)
    publisher.attach(subscriber2)

    publisher.news = "¡Nueva política económica!"
    publisher.news = "¡Evento deportivo importante!"

    # Strategy
    print("\n=== Strategy Pattern ===")
    context = PaymentContext(CreditCardPayment())
    print(context.execute_payment(100.50))

    context.strategy = PayPalPayment()
    print(context.execute_payment(250.75))

    context.strategy = CashPayment()
    print(context.execute_payment(50.00))

    # Edge cases
    print("\n=== Edge Cases ===")
    try:
        AnimalFactory.create_animal('elephant')
    except ValueError as e:
        print(f"Error esperado: {e}")

    try:
        db1.execute_query("SELECT * FROM users")
    except RuntimeError as e:
        print(f"Error esperado: {e}")

if __name__ == "__main__":
    main()

from typing import TypeVar, Generic, Protocol, overload, Union, List, Dict, Any, Optional
from abc import ABC, abstractmethod

# Definición de TypeVar para uso genérico
T = TypeVar('T')
U = TypeVar('U')
V = TypeVar('V')

# Protocolo para definir contrato de objetos que pueden ser serializados
class Serializable(Protocol):
    """Protocolo para objetos que pueden ser serializados a diccionario."""
    def to_dict(self) -> Dict[str, Any]: ...

# Protocolo para objetos que pueden ser comparados
class Comparable(Protocol):
    """Protocolo para objetos que pueden ser comparados."""
    def __lt__(self, other: 'Comparable') -> bool: ...
    def __eq__(self, other: 'Comparable') -> bool: ...

# Clase genérica que puede contener cualquier tipo
class Container(Generic[T]):
    """Contenedor genérico para almacenar un valor de tipo T."""

    def __init__(self, value: T) -> None:
        self._value: T = value

    def get(self) -> T:
        """Obtiene el valor almacenado."""
        return self._value

    def set(self, value: T) -> None:
        """Establece un nuevo valor."""
        self._value = value

    def __repr__(self) -> str:
        return f"Container({self._value!r})"

# Clase genérica con múltiples TypeVars
class Pair(Generic[T, U]):
    """Par genérico que almacena dos valores de tipos diferentes."""

    def __init__(self, first: T, second: U) -> None:
        self.first: T = first
        self.second: U = second

    def swap(self) -> 'Pair[U, T]':
        """Intercambia los valores del par."""
        return Pair(self.second, self.first)

    def __repr__(self) -> str:
        return f"Pair({self.first!r}, {self.second!r})"

# Sobrecarga de métodos con diferentes firmas
class Calculator:
    """Calculadora con sobrecarga de métodos."""

    @overload
    def add(self, a: int, b: int) -> int: ...

    @overload
    def add(self, a: float, b: float) -> float: ...

    @overload
    def add(self, a: str, b: str) -> str: ...

    @overload
    def add(self, a: List[T], b: List[T]) -> List[T]: ...

    def add(self, a: Union[int, float, str, List[T]], b: Union[int, float, str, List[T]]) -> Union[int, float, str, List[T]]:
        """
        Sobrecarga de método add para diferentes tipos.

        Args:
            a: Primer operando
            b: Segundo operando

        Returns:
            Resultado de la suma según el tipo de operandos

        Raises:
            TypeError: Si los tipos no son compatibles
        """
        if isinstance(a, list) and isinstance(b, list):
            return a + b
        elif isinstance(a, (int, float)) and isinstance(b, (int, float)):
            return a + b
        elif isinstance(a, str) and isinstance(b, str):
            return a + b
        else:
            raise TypeError("Tipos no compatibles para la operación add")

# Clase abstracta con métodos abstractos
class DataProcessor(ABC):
    """Clase abstracta para procesadores de datos."""

    @abstractmethod
    def process(self, data: T) -> U:
        """Procesa datos de tipo T y devuelve tipo U."""
        pass

    @abstractmethod
    def validate(self, data: T) -> bool:
        """Valida si los datos son válidos."""
        pass

# Implementación concreta de DataProcessor
class StringProcessor(DataProcessor[str, int]):
    """Procesador de cadenas que devuelve su longitud."""

    def process(self, data: str) -> int:
        """Devuelve la longitud de la cadena."""
        return len(data)

    def validate(self, data: str) -> bool:
        """Valida que la cadena no sea vacía."""
        return isinstance(data, str) and len(data) > 0

# Ejemplo de uso de Protocolos
class User:
    """Ejemplo de clase que implementa el protocolo Serializable."""

    def __init__(self, name: str, age: int) -> None:
        self.name = name
        self.age = age

    def to_dict(self) -> Dict[str, Any]:
        """Convierte el objeto a diccionario."""
        return {"name": self.name, "age": self.age}

# Ejemplo de uso de Comparable
class Number:
    """Ejemplo de clase que implementa Comparable."""

    def __init__(self, value: float) -> None:
        self.value = value

    def __lt__(self, other: 'Number') -> bool:
        return self.value < other.value

    def __eq__(self, other: 'Number') -> bool:
        return self.value == other.value

    def __repr__(self) -> str:
        return f"Number({self.value})"

# Función que usa protocolos
def process_serializable(obj: Serializable) -> Dict[str, Any]:
    """Procesa un objeto serializable y devuelve su representación."""
    return obj.to_dict()

# Función que ordena elementos comparables
def sort_comparable(items: List[Comparable]) -> List[Comparable]:
    """Ordena una lista de elementos comparables."""
    if not items:
        return []
    return sorted(items)

# Ejemplo de uso completo
def main() -> None:
    """Ejemplo completo de uso de los tipos avanzados."""

    # Uso de Container
    container_int = Container(42)
    container_str = Container("hello")
    print(f"Container int: {container_int.get()}")
    print(f"Container str: {container_str.get()}")

    # Uso de Pair
    pair_str_int = Pair("key", 123)
    pair_swapped = pair_str_int.swap()
    print(f"Original pair: {pair_str_int}")
    print(f"Swapped pair: {pair_swapped}")

    # Uso de Calculator
    calc = Calculator()
    print(f"Add int: {calc.add(1, 2)}")
    print(f"Add float: {calc.add(1.5, 2.5)}")
    print(f"Add str: {calc.add('hello', ' world')}")
    print(f"Add list: {calc.add([1, 2], [3, 4])}")

    # Uso de Protocolos
    user = User("Alice", 30)
    user_data = process_serializable(user)
    print(f"User data: {user_data}")

    # Uso de Comparable
    numbers = [Number(3.14), Number(2.71), Number(1.41)]
    sorted_numbers = sort_comparable(numbers)
    print(f"Sorted numbers: {sorted_numbers}")

    # Uso de DataProcessor
    processor = StringProcessor()
    print(f"String length: {processor.process('hello world')}")
    print(f"Validation result: {processor.validate('test')}")

if __name__ == "__main__":
    main()

