class Field:
    """Campo de modelo con opciones de validación."""

    def __init__(self, 
                 primary_key: bool = False,
                 nullable: bool = True,
                 default: Any = None,
                 unique: bool = False,
                 max_length: Optional[int] = None):
        self.primary_key = primary_key
        self.nullable = nullable
        self.default = default
        self.unique = unique
        self.max_length = max_length
        self.name = None  # Se asigna dinámicamente por el ORM

class CharField(Field):
    """Campo de texto de longitud variable."""
    pass

class IntegerField(Field):
    """Campo de número entero."""
    pass

class DateTimeField(Field):
    """Campo de fecha y hora."""
    pass

class BooleanField(Field):
    """Campo booleano."""
    pass

class ModelMeta(type):
    """Metaclase para modelos ORM."""

    def __new__(mcs, name: str, bases: tuple, attrs: dict):
        # Obtener campos definidos en la clase
        field_names = []
        for key, value in list(attrs.items()):
            if isinstance(value, Field):
                value.name = key
                field_names.append(key)

        # Guardar los campos en el modelo
        attrs['_fields'] = field_names
        attrs['_primary_key_field'] = None

        # Detectar campo primario
        for field_name in field_names:
            if attrs[field_name].primary_key:
                attrs['_primary_key_field'] = field_name
                break

        # Crear la clase
        cls = super().__new__(mcs, name, bases, attrs)

        # Asignar tipo a los campos
        hints = get_type_hints(cls)
        for field_name in field_names:
            field = attrs[field_name]
            if field_name in hints:
                field.type = hints[field_name]

        return cls

class Model(metaclass=ModelMeta):
    """Clase base para modelos ORM."""

    _fields: List[str] = []
    _primary_key_field: Optional[str] = None

    def __init__(self, **kwargs):
        # Asignar valores por defecto
        for field_name in self._fields:
            field = getattr(self.__class__, field_name)
            if field_name in kwargs:
                value = kwargs[field_name]
                self._validate_field(field_name, value)
                setattr(self, field_name, value)
            elif field.default is not None:
                setattr(self, field_name, field.default)
            elif field.primary_key:
                setattr(self, field_name, None)
            elif not field.nullable:
                raise ValueError(f"Campo {field_name} no puede ser nulo")
            else:
                setattr(self, field_name, None)

    def _validate_field(self, field_name: str, value: Any) -> None:
        """Valida un campo según sus restricciones."""
        field = getattr(self.__class__, field_name)

        if value is None and not field.nullable:
            raise ValueError(f"Campo {field_name} no puede ser nulo")

        if value is not None and isinstance(field, CharField):
            if field.max_length and len(str(value)) > field.max_length:
                raise ValueError(f"Campo {field_name} excede la longitud máxima de {field.max_length}")

        if value is not None and isinstance(field, IntegerField):
            if not isinstance(value, int):
                raise ValueError(f"Campo {field_name} debe ser un entero")

        if value is not None and isinstance(field, DateTimeField):
            if not isinstance(value, datetime):
                raise ValueError(f"Campo {field_name} debe ser una fecha")

        if value is not None and isinstance(field, BooleanField):
            if not isinstance(value, bool):
                raise ValueError(f"Campo {field_name} debe ser un booleano")

