class Database:
    """Base de datos en memoria para pruebas."""

    def __init__(self):
        self._data: Dict[Type, List[Model]] = {}

    def save(self, model: Model) -> None:
        """Guarda un modelo."""
        model_type = model.__class__
        if model_type not in self._data:
            self._data[model_type] = []

        # Si tiene PK, actualiza o crea
        if model._primary_key_field:
            pk_field = getattr(model.__class__, model._primary_key_field)
            if pk_field.primary_key and getattr(model, model._primary_key_field) is not None:
                # Actualizar
                for i, existing in enumerate(self._data[model_type]):
                    if getattr(existing, model._primary_key_field) == getattr(model, model._primary_key_field):
                        self._data[model_type][i] = model
                        return
            # Crear
            self._data[model_type].append(model)
        else:
            # Sin PK, simplemente añadir
            self._data[model_type].append(model)

