def process_data(data: str) -> str: ...

def process_data(data: Union[List[T], Dict[str, T], str]) -> Union[List[T], Dict[str, T], str]:
    """
    Procesa datos de diferentes tipos con sobrecarga.

    Args:
        data: Lista, diccionario o cadena a procesar

    Returns:
        Datos procesados según el tipo de entrada
    """
    if isinstance(data, list):
        return [item for item in data if item is not None]
    elif isinstance(data, dict):
        return {k: v for k, v in data.items() if v is not None}
    elif isinstance(data, str):
        return data.strip().lower()
    else:
        raise TypeError("Tipo de dato no soportado")

