from typing import TypeVar, Generic, Protocol, overload, List, Dict, Any, Union, Callable, Optional
from abc import ABC, abstractmethod

# TypeVar para tipos genéricos
T = TypeVar('T')
U = TypeVar('U')
V = TypeVar('V')

# Protocol para definir interfaces estructurales
class Drawable(Protocol):
    """Protocolo para objetos que pueden dibujarse."""
    def draw(self) -> None: ...

class Movable(Protocol):
    """Protocolo para objetos que pueden moverse."""
    def move(self, x: float, y: float) -> None: ...

# Generic class con múltiples TypeVars
class Pair(Generic[T, U]):
    """Clase genérica que almacena un par de valores de tipos diferentes."""

    def __init__(self, first: T, second: U) -> None:
        self.first = first
        self.second = second

    def get_first(self) -> T:
        """Obtiene el primer elemento."""
        return self.first

    def get_second(self) -> U:
        """Obtiene el segundo elemento."""
        return self.second

    def swap(self) -> 'Pair[U, T]':
        """Intercambia los elementos y devuelve un nuevo Pair."""
        return Pair(self.second, self.first)

    def __repr__(self) -> str:
        return f"Pair({self.first!r}, {self.second!r})"

# Protocolo para operaciones matemáticas
class MathOperation(Protocol[T]):
    """Protocolo para operaciones matemáticas."""
    def add(self, other: T) -> T: ...
    def multiply(self, scalar: float) -> T: ...

# Clase que implementa el protocolo MathOperation
class Vector:
    """Representa un vector 2D."""

    def __init__(self, x: float, y: float) -> None:
        self.x = x
        self.y = y

    def add(self, other: 'Vector') -> 'Vector':
        """Suma dos vectores."""
        return Vector(self.x + other.x, self.y + other.y)

    def multiply(self, scalar: float) -> 'Vector':
        """Multiplica el vector por un escalar."""
        return Vector(self.x * scalar, self.y * scalar)

    def __repr__(self) -> str:
        return f"Vector({self.x}, {self.y})"

# Sobrecarga de funciones
@overload
def process_data(data: List[int]) -> List[str]: ...

@overload
def process_data(data: List[str]) -> List[int]: ...

@overload
def process_data(data: List[Dict[str, Any]]) -> List[str]: ...

def process_data(data: Union[List[int], List[str], List[Dict[str, Any]]]) -> Union[List[str], List[int]]:
    """
    Procesa datos según su tipo.

    Args:
        data: Lista de enteros, strings o diccionarios

    Returns:
        Lista procesada según el tipo de entrada

    Raises:
        ValueError: Si el tipo de datos no es soportado
    """
    if not data:
        return []

    if isinstance(data[0], int):
        return [str(x) for x in data]
    elif isinstance(data[0], str):
        return [len(x) for x in data]
    elif isinstance(data[0], dict):
        return [str(x.get('id', 'unknown')) for x in data]
    else:
        raise ValueError("Tipo de dato no soportado")

# Función con múltiples sobrecargas
@overload
def calculate_area(shape: 'Rectangle') -> float: ...

@overload
def calculate_area(shape: 'Circle') -> float: ...

@overload
def calculate_area(shape: Drawable) -> float: ...

def calculate_area(shape: Union['Rectangle', 'Circle', Drawable]) -> float:
    """
    Calcula el área de una forma geométrica.

    Args:
        shape: Objeto drawable

    Returns:
        Área de la forma

    Raises:
        NotImplementedError: Si no se puede calcular el área
    """
    if hasattr(shape, 'width') and hasattr(shape, 'height'):
        return shape.width * shape.height
    elif hasattr(shape, 'radius'):
        return 3.14159 * shape.radius ** 2
    else:
