from typing import Any, Dict, Optional, Type, Union
from functools import wraps

class Descriptor:
    """
    Descriptor base para atributos que se pueden leer, escribir y eliminar.
    """
    def __init__(self, name: str):
        self.name = name

    def __get__(self, obj: Any, objtype: Optional[Type] = None) -> Any:
        if obj is None:
            return self
        return getattr(obj, f'_{self.name}', None)

    def __set__(self, obj: Any, value: Any) -> None:
        setattr(obj, f'_{self.name}', value)

    def __delete__(self, obj: Any) -> None:
        if hasattr(obj, f'_{self.name}'):
            delattr(obj, f'_{self.name}')

class ValidatedDescriptor(Descriptor):
    """
    Descriptor que valida los valores asignados.
    """
    def __init__(self, name: str, validator=None):
        super().__init__(name)
        self.validator = validator

    def __set__(self, obj: Any, value: Any) -> None:
        if self.validator is not None and not self.validator(value):
            raise ValueError(f"Valor inválido para {self.name}: {value}")
        super().__set__(obj, value)

class PositiveNumber(ValidatedDescriptor):
    """
    Descriptor para números positivos.
    """
    def __init__(self, name: str):
        super().__init__(name, lambda x: isinstance(x, (int, float)) and x > 0)

class StringDescriptor(ValidatedDescriptor):
    """
    Descriptor para cadenas de texto.
    """
    def __init__(self, name: str):
        super().__init__(name, lambda x: isinstance(x, str))

class MetaClass(type):
    """
    Metaclase que registra automáticamente los descriptores en una clase.
    """
    def __new__(cls, name: str, bases: tuple, namespace: Dict[str, Any], **kwargs) -> Type:
        # Registrar descriptores en la clase
        descriptors = {}
        for key, value in list(namespace.items()):
            if isinstance(value, Descriptor):
                descriptors[key] = value
                # Eliminar el descriptor del namespace para evitar conflictos
                namespace.pop(key)

        # Crear la clase con el nuevo namespace
        new_class = super().__new__(cls, name, bases, namespace)

        # Asignar descriptores a la clase
        for key, descriptor in descriptors.items():
            setattr(new_class, key, descriptor)

        return new_class

class Model(metaclass=MetaClass):
    """
    Clase base que usa metaclases y descriptores para manejar atributos validados.
    """
    def __init__(self, **kwargs):
        for key, value in kwargs.items():
            if hasattr(self.__class__, key) and isinstance(getattr(self.__class__, key), Descriptor):
                setattr(self, key, value)
            else:
                setattr(self, key, value)

    def __repr__(self) -> str:
        attrs = ', '.join(f'{k}={v!r}' for k, v in self.__dict__.items())
        return f'{self.__class__.__name__}({attrs})'

class User(Model):
    """
    Ejemplo de clase que usa descriptores y metaclases.
    """
    name = StringDescriptor('name')
    age = PositiveNumber('age')
    email = StringDescriptor('email')

    def __init__(self, name: str, age: Union[int, float], email: str):
        super().__init__(name=name, age=age, email=email)

class Product(Model):
    """
    Otro ejemplo de clase con descriptores.
    """
    title = StringDescriptor('title')
    price = PositiveNumber('price')
    description = StringDescriptor('description')

    def __init__(self, title: str, price: Union[int, float], description: str):
        super().__init__(title=title, price=price, description=description)

class CachedDescriptor(Descriptor):
    """
    Descriptor con caché para evitar cálculos redundantes.
    """
    def __init__(self, name: str, func=None):
        super().__init__(name)
        self.func = func
        self.cache_name = f'_cache_{name}'

    def __get__(self, obj: Any, objtype: Optional[Type] = None) -> Any:
        if obj is None:
            return self

        if hasattr(obj, self.cache_name):
            return getattr(obj, self.cache_name)

        if self.func is not None:
            value = self.func(obj)
            setattr(obj, self.cache_name, value)
            return value

        return super().__get__(obj, objtype)

    def __set__(self, obj: Any, value: Any) -> None:
        setattr(obj, self.cache_name, value)
        super().__set__(obj, value)

class MathModel(Model):
    """
    Modelo que usa un descriptor con caché.
    """
    x = PositiveNumber('x')
    y = PositiveNumber('y')

    @CachedDescriptor('sum')
    def sum(self) -> float:
        return self.x + self.y

    @CachedDescriptor('product')
    def product(self) -> float:
        return self.x * self.y

