# --- IMPLEMENTACIÓN DE DATACLASSES DESDE CERO ---

def dataclass(cls):
    """Decorador para crear dataclasses con características básicas."""
    # Guardar atributos originales
    original_init = getattr(cls, '__init__', None)

    # Generar __init__ automáticamente
    def __init__(self, **kwargs):
        # Validar que todos los parámetros estén definidos en la clase
        fields = {k: v for k, v in cls.__annotations__.items() if not k.startswith('_')}
        for field_name, field_type in fields.items():
            if field_name in kwargs:
                setattr(self, field_name, kwargs[field_name])
            elif hasattr(cls, field_name):
                setattr(self, field_name, getattr(cls, field_name))
            else:
                # Atributo sin valor por defecto, verificar si es obligatorio
                if not hasattr(cls, f'_{field_name}_default'):
                    raise TypeError(f"__init__() missing 1 required positional argument: '{field_name}'")

    # Generar __repr__
    def __repr__(self):
        attrs = ', '.join(f'{k}={getattr(self, k)!r}' for k in cls.__annotations__.keys() if not k.startswith('_'))
        return f'{cls.__name__}({attrs})'

    # Generar __eq__
    def __eq__(self, other):
        if not isinstance(other, cls):
            return False
        return all(getattr(self, k) == getattr(other, k) for k in cls.__annotations__.keys() if not k.startswith('_'))

    # Generar __hash__ solo si es frozen
    def __hash__(self):
        return hash(tuple(getattr(self, k) for k in cls.__annotations__.keys() if not k.startswith('_')))

    # Añadir métodos a la clase
    cls.__init__ = __init__
    cls.__repr__ = __repr__
    cls.__eq__ = __eq__

    # Añadir __hash__ solo si es frozen
    if getattr(cls, '__frozen__', False):
        cls.__hash__ = __hash__

    return cls

def frozen(cls):
    """Decorador para hacer una dataclass inmutable."""
    # Añadir el atributo frozen
    cls.__frozen__ = True

    # Sobrescribir __setattr__ para evitar modificaciones
    def __setattr__(self, name, value):
        if hasattr(self, '__frozen__') and self.__frozen__:
            raise AttributeError(f"Cannot assign to field '{name}' in frozen class")
        object.__setattr__(self, name, value)

    cls.__setattr__ = __setattr__
    return cls

# --- IMPLEMENTACIÓN DE VALIDADORES Y CONVERTIDORES ---

def validator(func: Callable) -> Callable:
    """Decorador para validar campos."""
    @wraps(func)
    def wrapper(self, value):
        if not func(value):
            raise ValueError(f"Validation failed for {func.__name__}")
        return value
    return wrapper

def converter(func: Callable) -> Callable:
    """Decorador para convertir valores."""
    @wraps(func)
    def wrapper(self, value):
        return func(value)
    return wrapper

# --- IMPLEMENTACIÓN DE ATTRS DESDE CERO ---

class attr:
    """Clase para definir atributos con validadores y convertidores."""
    def __init__(self, default: Any = None, validator: Optional[Callable] = None, converter: Optional[Callable] = None, init: bool = True):
        self.default = default
        self.validator = validator
        self.converter = converter
        self.init = init
        self.name = None

    def __set_name__(self, owner, name):
        self.name = name

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        return getattr(obj, f'_{self.name}', self.default)

    def __set__(self, obj, value):
        # Aplicar conversión si existe
        if self.converter:
            try:
                value = self.converter(value)
            except Exception as e:
                raise ValueError(f"Conversion failed for {self.name}: {e}")

        # Aplicar validación si existe
        if self.validator:
            try:
                if not self.validator(value):
                    raise ValueError(f"Validation failed for {self.name}")
            except Exception as e:
                raise ValueError(f"Validation failed for {self.name}: {e}")

        # Establecer el valor
        setattr(obj, f'_{self.name}', value)

# Ejemplo de validadores y convertidores
def is_positive(value):
