    return isinstance(value, str)

def to_int(value):
    """Convertidor a entero."""
    if isinstance(value, str):
        return int(value)
    return int(value)

def to_lower(value):
    """Convertidor a minúsculas."""
    if isinstance(value, str):
        return value.lower()
    return str(value).lower()

