from collections import deque
from typing import List, Dict, Tuple, Optional, Set, Union
import heapq

class Graph:
    """
    Representación de un grafo no dirigido con pesos en las aristas.
    """
    def __init__(self):
        self.adj_list: Dict[int, List[Tuple[int, int]]] = {}  # nodo: [(vecino, peso), ...]

    def add_edge(self, u: int, v: int, weight: int = 1) -> None:
        """Agrega una arista entre nodos u y v con peso dado."""
        if u not in self.adj_list:
            self.adj_list[u] = []
        if v not in self.adj_list:
            self.adj_list[v] = []
        self.adj_list[u].append((v, weight))
        self.adj_list[v].append((u, weight))  # Grafo no dirigido

    def get_neighbors(self, node: int) -> List[Tuple[int, int]]:
        """Devuelve una lista de vecinos con sus pesos."""
        return self.adj_list.get(node, [])

def bfs(graph: Graph, start: int, target: int = None) -> Union[List[int], Dict[int, int]]:
    """
    BFS (Breadth-First Search) para encontrar caminos en un grafo.

    Args:
        graph: Grafo a recorrer.
        start: Nodo inicial.
        target: Nodo objetivo (opcional). Si se proporciona, devuelve el camino a él.

    Returns:
        Si target no se proporciona: lista de nodos visitados en orden.
        Si target se proporciona: diccionario de padres para reconstruir el camino.
    """
    if start not in graph.adj_list:
        return [] if target is None else {}

    visited: Set[int] = set()
    queue: deque = deque([start])
    visited.add(start)

    if target is None:
        result = [start]
        while queue:
            node = queue.popleft()
            for neighbor, _ in graph.get_neighbors(node):
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
                    result.append(neighbor)
        return result

    # BFS para encontrar camino a target
    parent: Dict[int, int] = {start: None}
    while queue:
        node = queue.popleft()
        if node == target:
            break
        for neighbor, _ in graph.get_neighbors(node):
            if neighbor not in visited:
                visited.add(neighbor)
                parent[neighbor] = node
                queue.append(neighbor)

    return parent

def dfs(graph: Graph, start: int, target: int = None) -> Union[List[int], Dict[int, int]]:
    """
    DFS (Depth-First Search) para encontrar caminos en un grafo.

    Args:
        graph: Grafo a recorrer.
        start: Nodo inicial.
        target: Nodo objetivo (opcional). Si se proporciona, devuelve el camino a él.

    Returns:
        Si target no se proporciona: lista de nodos visitados en orden.
        Si target se proporciona: diccionario de padres para reconstruir el camino.
    """
    if start not in graph.adj_list:
        return [] if target is None else {}

    visited: Set[int] = set()
    stack: List[int] = [start]
    visited.add(start)

    if target is None:
        result = [start]
        while stack:
            node = stack.pop()
            for neighbor, _ in graph.get_neighbors(node):
                if neighbor not in visited:
                    visited.add(neighbor)
                    stack.append(neighbor)
                    result.append(neighbor)
        return result

    # DFS para encontrar camino a target
    parent: Dict[int, int] = {start: None}
    while stack:
        node = stack.pop()
        if node == target:
            break
        for neighbor, _ in graph.get_neighbors(node):
            if neighbor not in visited:
                visited.add(neighbor)
                parent[neighbor] = node
                stack.append(neighbor)

    return parent

def dijkstra(graph: Graph, start: int, end: int = None) -> Union[Dict[int, int], Tuple[Dict[int, int], int]]:
    """
    Algoritmo de Dijkstra para encontrar el camino más corto en un grafo con pesos no negativos.

    Args:
        graph: Grafo con pesos.
        start: Nodo inicial.
        end: Nodo final (opcional). Si se proporciona, también devuelve la distancia.

    Returns:
        Si end no se proporciona: diccionario de distancias mínimas desde start.
        Si end se proporciona: (distancias, distancia al nodo final).
    """
    if start not in graph.adj_list:
        return {} if end is None else ({}, float('inf'))

    distances: Dict[int, int] = {node: float('inf') for node in graph.adj_list}
    distances[start] = 0
    parent: Dict[int, int] = {start: None}
    visited: Set[int] = set()

    # Cola de prioridad: (distancia, nodo)
    pq = [(0, start)]

    while pq:
        current_dist, current_node = heapq.heappop(pq)

        if current_node in visited:
            continue

        visited.add(current_node)

        if end is not None and current_node == end:
            break

        for neighbor, weight in graph.get_neighbors(current_node):
            if neighbor not in visited:
                new_dist = current_dist + weight
                if new_dist < distances[neighbor]:
                    distances[neighbor] = new_dist
                    parent[neighbor] = current_node
                    heapq.heappush(pq, (new_dist, neighbor))

    if end is None:
        return distances
    else:
        return (distances, distances[end] if distances[end] != float('inf') else float('inf'))

def reconstruct_path(parent: Dict[int, int], start: int, end: int) -> List[int]:
    """
    Reconstruye el camino desde start hasta end usando el diccionario de padres.

    Args:
        parent: Diccionario de padres devuelto por BFS/DFS.
        start: Nodo inicial.
        end: Nodo final.

    Returns:
        Lista con el camino desde start a end.
    """
    if end not in parent:
        return []

    path = []
    current = end
    while current is not None:
        path.append(current)

