# Singleton Pattern
class SingletonMeta(type):
    """
    Metaclase para implementar el patrón Singleton.
    Garantiza que solo exista una instancia de la clase.
    """
    _instances: Dict[type, Any] = {}

    def __call__(cls, *args, **kwargs):
        if cls not in cls._instances:
            cls._instances[cls] = super().__call__(*args, **kwargs)
        return cls._instances[cls]

class DatabaseConnection(metaclass=SingletonMeta):
    """
    Ejemplo de clase singleton que representa una conexión a base de datos.
    """
    def __init__(self) -> None:
        self.connection_string = "postgresql://localhost:5432/mydb"
        self.is_connected = False

    def connect(self) -> None:
        """Establece la conexión a la base de datos."""
        self.is_connected = True

    def disconnect(self) -> None:
        """Cierra la conexión a la base de datos."""
        self.is_connected = False

    def execute_query(self, query: str) -> str:
        """Ejecuta una consulta SQL."""
        if not self.is_connected:
            raise RuntimeError("No hay conexión activa a la base de datos")
        return f"Resultado de la consulta: {query}"

# Factory Pattern
class PaymentProcessor(ABC):
    """
    Clase abstracta para procesadores de pago.
    """
    @abstractmethod
    def process_payment(self, amount: float) -> bool:
        """Procesa un pago de un monto específico."""
        pass

class CreditCardProcessor(PaymentProcessor):
    """Procesador de pago con tarjeta de crédito."""
    def process_payment(self, amount: float) -> bool:
        return amount > 0

class PayPalProcessor(PaymentProcessor):
    """Procesador de pago con PayPal."""
    def process_payment(self, amount: float) -> bool:
        return amount > 0

class PaymentProcessorFactory:
    """
    Factoría para crear procesadores de pago según el tipo especificado.
    """
    @staticmethod
    def create_processor(processor_type: str) -> PaymentProcessor:
        """
        Crea un procesador de pago según el tipo especificado.

        Args:
            processor_type: Tipo de procesador ('credit_card' o 'paypal')

        Returns:
            Instancia del procesador de pago correspondiente

        Raises:
            ValueError: Si el tipo de procesador no es válido
        """
        if processor_type == "credit_card":
            return CreditCardProcessor()
        elif processor_type == "paypal":
            return PayPalProcessor()
        else:
            raise ValueError(f"Tipo de procesador no soportado: {processor_type}")

# Observer Pattern
class Observer(ABC):
    """
    Interfaz para observadores.
    """
    @abstractmethod
    def update(self, message: str) -> None:
        """Método llamado cuando el sujeto notifica un cambio."""
        pass

class Subject:
    """
    Clase sujeto que mantiene una lista de observadores.
    """
    def __init__(self) -> None:
        self._observers: List[Observer] = []

    def attach(self, observer: Observer) -> None:
        """Agrega un observador."""
        if observer not in self._observers:
            self._observers.append(observer)

    def detach(self, observer: Observer) -> None:
        """Elimina un observador."""
        if observer in self._observers:
            self._observers.remove(observer)

    def notify(self, message: str) -> None:
        """Notifica a todos los observadores."""
        for observer in self._observers:
            observer.update(message)

class OrderStatusObserver(Observer):
    """Observador que registra cambios en el estado del pedido."""
    def __init__(self, name: str) -> None:
        self.name = name

    def update(self, message: str) -> None:
        print(f"Observador {self.name}: {message}")

class NotificationService(Subject):
    """Servicio de notificaciones que extiende Subject."""
    def __init__(self) -> None:
        super().__init__()
        self._status = "pending"

    def set_status(self, status: str) -> None:
        """Establece el estado y notifica a los observadores."""
        self._status = status
        self.notify(f"Estado del pedido cambiado a: {status}")

# Strategy Pattern
class ShippingStrategy(ABC):
    """
    Estrategia abstracta para calcular el costo de envío.
    """
    @abstractmethod
    def calculate_cost(self, weight: float) -> float:
        """Calcula el costo de envío según el peso."""
        pass

class StandardShipping(ShippingStrategy):
    """Estrategia de envío estándar."""
    def calculate_cost(self, weight: float) -> float:
        return weight * 5.0

class ExpressShipping(ShippingStrategy):
    """Estrategia de envío express."""
    def calculate_cost(self, weight: float) -> float:
        return weight * 10.0

class ShippingCalculator:
    """
    Calculadora de envío que utiliza una estrategia.
    """
    def __init__(self, strategy: ShippingStrategy) -> None:
        self._strategy = strategy

    def set_strategy(self, strategy: ShippingStrategy) -> None:
        """Cambia la estrategia de cálculo."""
        self._strategy = strategy

    def calculate(self, weight: float) -> float:
        """Calcula el costo de envío usando la estrategia actual."""
        if weight <= 0:
            raise ValueError("El peso debe ser mayor que cero")
        return self._strategy.calculate_cost(weight)

# Ejemplo de uso completo
def main() -> None:
    # Singleton
    print("=== Singleton Pattern ===")
    db1 = DatabaseConnection()
    db2 = DatabaseConnection()
    print(f"Misma instancia: {db1 is db2}")
    db1.connect()
    print(f"Conectado: {db1.is_connected}")
    print(db1.execute_query("SELECT * FROM users"))

    # Factory
    print("\n=== Factory Pattern ===")
    try:
        processor1 = PaymentProcessorFactory.create_processor("credit_card")
        processor2 = PaymentProcessorFactory.create_processor("paypal")
        print(f"Procesador 1: {type(processor1).__name__}")
        print(f"Procesador 2: {type(processor2).__name__}")
        print(f"Procesamiento exitoso: {processor1.process_payment(100.0)}")
    except ValueError as e:
        print(f"Error: {e}")

    # Observer
    print("\n=== Observer Pattern ===")
    notification_service = NotificationService()
    observer1 = OrderStatusObserver("Notificador 1")
    observer2 = OrderStatusObserver("Notificador 2")

    notification_service.attach(observer1)
    notification_service.attach(observer2)
    notification_service.set_status("processing")
    notification_service.detach(observer1)
    notification_service.set_status("shipped")

    # Strategy
    print("\n=== Strategy Pattern ===")
    calculator = ShippingCalculator(StandardShipping())
    print(f"Costo estándar (2kg): ${calculator.calculate(2.0)}")

    calculator.set_strategy(ExpressShipping())
    print(f"Costo express (2kg): ${calculator.calculate(2.0)}")

if __name__ == "__main__":
    main()

from functools import wraps
from time import time, sleep
from typing import Any, Callable, TypeVar, Dict, Optional
from collections import defaultdict
import random

# Tipos genéricos para decoradores
F = TypeVar('F', bound=Callable)

def memoize(func: F) -> F:
    """
    Decorador que memoiza resultados de funciones.

    Complejidad: O(1) para acceso, O(n) para cálculo en caso de cache miss.
    """
    cache: Dict[Any, Any] = {}

    @wraps(func)
    def wrapper(*args, **kwargs):
        # Crear clave única para el cache
        key = str(args) + str(sorted(kwargs.items()))
        if key in cache:
            return cache[key]
        result = func(*args, **kwargs)
        cache[key] = result
        return result

    # Añadir método para limpiar cache
    wrapper.clear_cache = lambda: cache.clear()
    return wrapper

def timer(func: F) -> F:
    """
    Decorador que mide el tiempo de ejecución de una función.

    Complejidad: O(1) para medición, O(n) para ejecución de función.
    """
    @wraps(func)
    def wrapper(*args, **kwargs):
        start = time()
        result = func(*args, **kwargs)
        end = time()
        print(f"{func.__name__} ejecutado en {end - start:.4f} segundos")
        return result
    return wrapper

def retry(max_attempts: int = 3, delay: float = 1.0, backoff: float = 1.0) -> Callable[[F], F]:
    """
    Decorador que reintenta ejecutar una función en caso de fallo.

    Complejidad: O(n) donde n es el número de intentos.
    """
    def decorator(func: F) -> F:
        @wraps(func)
        def wrapper(*args, **kwargs):
            attempts = 0
            current_delay = delay

            while attempts < max_attempts:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    attempts += 1
                    if attempts >= max_attempts:
                        raise e
                    print(f"Intento {attempts} fallido: {e}. Reintentando en {current_delay}s...")
                    sleep(current_delay)
                    current_delay *= backoff
            return None
        return wrapper
    return decorator

def rate_limit(max_calls: int = 10, time_window: float = 1.0) -> Callable[[F], F]:
    """
    Decorador que limita la cantidad de llamadas a una función por ventana de tiempo.

    Complejidad: O(n) donde n es el número de llamadas anteriores en ventana.
    """
    def decorator(func: F) -> F:
        # Almacena timestamps de llamadas
        call_times: list = []

        @wraps(func)
        def wrapper(*args, **kwargs):
            now = time()
            # Elimina llamadas anteriores a la ventana
            call_times[:] = [t for t in call_times if now - t < time_window]

            if len(call_times) >= max_calls:
                # Calcula tiempo de espera
                wait_time = time_window - (now - call_times[0])
                if wait_time > 0:
                    print(f"Rate limit alcanzado. Esperando {wait_time:.2f}s...")
                    sleep(wait_time)
                # Elimina la más antigua
                call_times.pop(0)

            # Añade la nueva llamada
            call_times.append(now)
            return func(*args, **kwargs)
        return wrapper
    return decorator

# Ejemplos de uso
if __name__ == "__main__":
    # Ejemplo memoize
    @memoize
    def fibonacci(n: int) -> int:
        """Calcula el n-ésimo número de Fibonacci."""
        if n < 2:
            return n
        return fibonacci(n-1) + fibonacci(n-2)

    print("Fibonacci(10):", fibonacci(10))
    fibonacci.clear_cache()
    print("Después de limpiar cache:", fibonacci(10))

    # Ejemplo timer
    @timer
    def slow_function():
        """Función lenta para medir tiempo."""
        sleep(0.1)
        return "Hecho"

    slow_function()

    # Ejemplo retry
    @retry(max_attempts=3, delay=0.1)
    def unreliable_function():
        """Función que falla aleatoriamente."""
        if random.random() < 0.7:
            raise Exception("Error aleatorio")
        return "Éxito"

    try:
        print("Resultado de unreliable_function:", unreliable_function())
    except Exception as e:
        print("Error final:", e)

    # Ejemplo rate_limit
    @rate_limit(max_calls=2, time_window=2.0)
    def limited_function():
        """Función con límite de llamadas."""
        return "Llamada permitida"

    for i in range(5):
        try:
            print(f"Llamada {i+1}:", limited_function())
        except Exception as e:
            print(f"Error en llamada {i+1}:", e)

from typing import Optional, List, Any, Callable
from collections import deque

# Linked List Implementation
class ListNode:
    """Node for a singly linked list."""
    def __init__(self, val: int = 0, next: Optional['ListNode'] = None):
        self.val = val
        self.next = next

class LinkedList:
    """Singly linked list implementation."""
    def __init__(self):
        self.head: Optional[ListNode] = None
        self.size = 0

    def append(self, val: int) -> None:
        """Add a node with value at the end of the list."""
        new_node = ListNode(val)
        if not self.head:
            self.head = new_node
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = new_node
        self.size += 1

    def prepend(self, val: int) -> None:
        """Add a node with value at the beginning of the list."""
        new_node = ListNode(val, self.head)
        self.head = new_node
        self.size += 1

    def delete(self, val: int) -> bool:
        """Delete the first occurrence of a value. Return True if deleted."""
        if not self.head:
            return False

        if self.head.val == val:
            self.head = self.head.next
            self.size -= 1
            return True

        current = self.head
        while current.next:
            if current.next.val == val:
                current.next = current.next.next
                self.size -= 1
                return True
            current = current.next
        return False

    def find(self, val: int) -> Optional[ListNode]:
        """Find and return the first node with the given value."""
        current = self.head
        while current:
            if current.val == val:
                return current
            current = current.next
        return None

    def to_list(self) -> List[int]:
        """Convert linked list to Python list."""
        result = []
        current = self.head
        while current:
            result.append(current.val)
            current = current.next
        return result

    def __len__(self) -> int:
        return self.size

# Binary Search Tree Implementation
class TreeNode:
    """Node for a binary search tree."""
    def __init__(self, val: int = 0, left: Optional['TreeNode'] = None, right: Optional['TreeNode'] = None):
        self.val = val
        self.left = left
        self.right = right

class BST:
    """Binary Search Tree implementation."""
    def __init__(self):
        self.root: Optional[TreeNode] = None

    def insert(self, val: int) -> None:
        """Insert a value into the BST."""
        self.root = self._insert_recursive(self.root, val)

    def _insert_recursive(self, node: Optional[TreeNode], val: int) -> TreeNode:
        if not node:
            return TreeNode(val)
        if val < node.val:
            node.left = self._insert_recursive(node.left, val)
        elif val > node.val:
            node.right = self._insert_recursive(node.right, val)
        return node

    def search(self, val: int) -> bool:
        """Search for a value in the BST."""
        return self._search_recursive(self.root, val)

    def _search_recursive(self, node: Optional[TreeNode], val: int) -> bool:
        if not node:
            return False
        if node.val == val:
            return True
        if val < node.val:
            return self._search_recursive(node.left, val)
        else:
            return self._search_recursive(node.right, val)

    def delete(self, val: int) -> bool:
        """Delete a value from the BST. Return True if deleted."""
        self.root, deleted = self._delete_recursive(self.root, val)
        return deleted

    def _delete_recursive(self, node: Optional[TreeNode], val: int) -> tuple[Optional[TreeNode], bool]:
        if not node:
            return node, False

        if val < node.val:
            node.left, deleted = self._delete_recursive(node.left, val)
        elif val > node.val:
            node.right, deleted = self._delete_recursive(node.right, val)
        else:
            # Node to delete found
            deleted = True
            # Case 1: Node has no children
            if not node.left and not node.right:
                return None, deleted
            # Case 2: Node has one child
            if not node.left:
                return node.right, deleted
            if not node.right:
                return node.left, deleted
            # Case 3: Node has two children
            # Find inorder successor (smallest in right subtree)
            successor = self._find_min(node.right)
            node.val = successor.val
            node.right, _ = self._delete_recursive(node.right, successor.val)

        return node, deleted

    def _find_min(self, node: TreeNode) -> TreeNode:
        """Find the minimum value node in a subtree."""
        while node.left:
            node = node.left
        return node

    def inorder_traversal(self) -> List[int]:
        """Return inorder traversal of the BST."""
        result = []
        self._inorder_recursive(self.root, result)
        return result

    def _inorder_recursive(self, node: Optional[TreeNode], result: List[int]) -> None:
        if node:
            self._inorder_recursive(node.left, result)
            result.append(node.val)
            self._inorder_recursive(node.right, result)

    def preorder_traversal(self) -> List[int]:
        """Return preorder traversal of the BST."""
        result = []
        self._preorder_recursive(self.root, result)
        return result

    def _preorder_recursive(self, node: Optional[TreeNode], result: List[int]) -> None:
        if node:
            result.append(node.val)
            self._preorder_recursive(node.left, result)
            self._preorder_recursive(node.right, result)

# Heap Implementation (Min Heap)
class MinHeap:
    """Min Heap implementation."""
    def __init__(self):
        self.heap: List[int] = []

    def push(self, val: int) -> None:
        """Add a value to the heap."""
        self.heap.append(val)
        self._heapify_up(len(self.heap) - 1)

    def pop(self) -> int:
        """Remove and return the minimum value from the heap."""
        if not self.heap:
            raise IndexError("pop from empty heap")

        if len(self.heap) == 1:
            return self.heap.pop()

        root = self.heap[0]
        self.heap[0] = self.heap.pop()
        self._heapify_down(0)
        return root

    def peek(self) -> int:
        """Return the minimum value without removing it."""
        if not self.heap:
            raise IndexError("peek from empty heap")
        return self.heap[0]

    def _heapify_up(self, index: int) -> None:
        """Move element up to maintain heap property."""
        parent_index = (index - 1) // 2
        if index > 0 and self.heap[index] < self.heap[parent_index]:
            self.heap[index], self.heap[parent_index] = self.heap[parent_index], self.heap[index]
            self._heapify_up(parent_index)

    def _heapify_down(self, index: int) -> None:
        """Move element down to maintain heap property."""
        smallest = index
        left_child = 2 * index + 1
        right_child = 2 * index + 2

        if (left_child < len(self.heap) and 
            self.heap[left_child] < self.heap[smallest]):
            smallest = left_child

        if (right_child < len(self.heap) and 
            self.heap[right_child] < self.heap[smallest]):
            smallest = right_child

        if smallest != index:
            self.heap[index], self.heap[smallest] = self.heap[smallest], self.heap[index]
            self._heapify_down(smallest)

    def size(self) -> int:
        """Return the size of the heap."""
        return len(self.heap)

    def is_empty(self) -> bool:
        """Check if the heap is empty."""
        return len(self.heap) == 0

# Graph Implementation (Adjacency List)
class Graph:
    """Graph implementation using adjacency list."""
    def __init__(self, directed: bool = False):
        self.graph: dict[int, List[int]] = {}
        self.directed = directed

    def add_vertex(self, vertex: int) -> None:
        """Add a vertex to the graph."""
        if vertex not in self.graph:
            self.graph[vertex] = []

    def add_edge(self, from_vertex: int, to_vertex: int) -> None:
        """Add an edge between two vertices."""
        self.add_vertex(from_vertex)
        self.add_vertex(to_vertex)
        self.graph[from_vertex].append(to_vertex)
        if not self.directed:
            self.graph[to_vertex].append(from_vertex)

    def remove_vertex(self, vertex: int) -> None:
        """Remove a vertex and all its edges."""
        if vertex in self.graph:
            # Remove all edges to this vertex
            for v in self.graph:
                if vertex in self.graph[v]:
                    self.graph[v].remove(vertex)
            # Remove the vertex itself
            del self.graph[vertex]

    def remove_edge(self, from_vertex: int, to_vertex: int) -> bool:
        """Remove an edge between two vertices. Return True if removed."""
        if from_vertex in self.graph and to_vertex in self.graph[from_vertex]:
            self.graph[from_vertex].remove(to_vertex)
            if not self.directed and from_vertex != to_vertex:
                self.graph[to_vertex].remove(from_vertex)
            return True
        return False

    def get_neighbors(self, vertex: int) -> List[int]:
        """Get all neighbors of a vertex."""
        return self.graph.get(vertex, [])

    def has_edge(self, from_vertex: int, to_vertex: int) -> bool:
        """Check if an edge exists between two vertices."""
        return to_vertex in self.graph.get(from_vertex, [])

    def dfs(self, start: int, visit_func: Callable[[int], None] = print) -> None:
        """Depth-first search starting from a vertex."""
        visited = set()
        self._dfs_recursive(start, visited, visit_func)

    def _dfs_recursive(self, vertex: int, visited: set, visit_func: Callable[[int], None]) -> None:
        visited.add(vertex)
        visit_func(vertex)
        for neighbor in self.graph.get(vertex, []):
            if neighbor not in visited:
                self._dfs_recursive(neighbor, visited, visit_func)

    def bfs(self, start: int, visit_func: Callable[[int], None] = print) -> None:
        """Breadth-first search starting from a vertex."""
        visited = set()
        queue = deque([start])
        visited.add(start)

        while queue:
            vertex = queue.popleft()
            visit_func(vertex)
            for neighbor in self.graph.get(vertex, []):
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

    def get_vertices(self) -> List[int]:
        """Get all vertices in the graph."""
        return list(self.graph.keys())

    def get_edges(self) -> List[tuple[int, int]]:
        """Get all edges in the graph."""
        edges = []
        for vertex, neighbors in self.graph.items():
            for neighbor in neighbors:
                if not self.directed or vertex <= neighbor:
                    edges.append((vertex, neighbor))
        return edges

