from typing import TypeVar, Generic, Protocol, overload, List, Dict, Any, Union, Optional
from abc import ABC, abstractmethod

# TypeVar para crear variables de tipo genérico
T = TypeVar('T')
U = TypeVar('U')
V = TypeVar('V')

# Protocol para definir contratos de tipo
class Drawable(Protocol):
    """Protocolo para objetos que pueden dibujarse."""
    def draw(self) -> None: ...

class Movable(Protocol):
    """Protocolo para objetos que pueden moverse."""
    def move(self, x: float, y: float) -> None: ...

# Clase genérica con múltiples TypeVars
class Container(Generic[T, U]):
    """Contenedor genérico que almacena elementos de dos tipos diferentes."""

    def __init__(self, first: T, second: U) -> None:
        self.first = first
        self.second = second

    def get_first(self) -> T:
        """Obtiene el primer elemento."""
        return self.first

    def get_second(self) -> U:
        """Obtiene el segundo elemento."""
        return self.second

    def swap(self) -> 'Container[U, T]':
        """Intercambia los tipos de los elementos."""
        return Container(self.second, self.first)

# Clase base para demostrar herencia genérica
class BaseProcessor(Generic[T]):
    """Procesador base genérico."""

    def __init__(self, data: List[T]) -> None:
        self.data = data

    def process(self) -> List[T]:
        """Procesa los datos."""
        return self.data

# Clase derivada con sobrecarga de métodos
class DataProcessor(BaseProcessor[T]):
    """Procesador de datos con sobrecarga de métodos."""

    @overload
    def process(self, filter_func: None = None) -> List[T]: ...

    @overload
    def process(self, filter_func: callable) -> List[T]: ...

    def process(self, filter_func=None):
        """Procesa los datos con filtro opcional."""
        if filter_func is None:
            return self.data
        return [item for item in self.data if filter_func(item)]

# Función con múltiples sobrecargas
@overload
def calculate_area(shape: Dict[str, float]) -> float: ...

@overload
def calculate_area(shape: List[float]) -> float: ...

@overload
def calculate_area(shape: str) -> float: ...

def calculate_area(shape: Union[Dict[str, float], List[float], str]) -> float:
    """Calcula el área de diferentes formas geométricas."""
    if isinstance(shape, dict):
        if 'radius' in shape:
            return 3.14159 * shape['radius'] ** 2
        elif 'width' in shape and 'height' in shape:
            return shape['width'] * shape['height']
    elif isinstance(shape, list):
        if len(shape) == 2:
            return shape[0] * shape[1]
    elif isinstance(shape, str):
        if shape == 'circle':
            return 3.14159 * 2 ** 2
        elif shape == 'rectangle':
            return 2 * 3
    return 0.0

# Clase con métodos sobrecargados
class Calculator:
    """Calculadora con métodos sobrecargados."""

    @overload
    def add(self, a: int, b: int) -> int: ...

    @overload
    def add(self, a: float, b: float) -> float: ...

    @overload
    def add(self, a: str, b: str) -> str: ...

    def add(self, a: Union[int, float, str], b: Union[int, float, str]) -> Union[int, float, str]:
        """Suma dos valores según su tipo."""
        if isinstance(a, str) and isinstance(b, str):
            return a + b
        elif isinstance(a, (int, float)) and isinstance(b, (int, float)):
            return a + b
        raise TypeError("Tipos no compatibles para la suma")

# Función que usa Protocolos
def render_objects(objects: List[Drawable]) -> None:
    """Renderiza una lista de objetos dibujables."""
    for obj in objects:
        obj.draw()

# Función que usa múltiples Protocolos
def move_objects(objects: List[Movable], x: float, y: float) -> None:
    """Mueve una lista de objetos movibles."""
    for obj in objects:
        obj.move(x, y)

