from abc import ABC, abstractmethod
from typing import List, Any, Dict, Optional
from enum import Enum

# Singleton Pattern
class SingletonMeta(type):
    """Metaclase para implementar el patrón Singleton."""
    _instances = {}

    def __call__(cls, *args, **kwargs):
        if cls not in cls._instances:
            cls._instances[cls] = super().__call__(*args, **kwargs)
        return cls._instances[cls]

class DatabaseConnection(metaclass=SingletonMeta):
    """Ejemplo de clase Singleton para conexión a base de datos."""

    def __init__(self) -> None:
        self._connection_string = "db://localhost:5432/mydb"
        self._connected = False

    def connect(self) -> None:
        """Conecta a la base de datos."""
        self._connected = True

    def disconnect(self) -> None:
        """Desconecta de la base de datos."""
        self._connected = False

    def is_connected(self) -> bool:
        """Verifica si está conectado."""
        return self._connected

    def get_connection_string(self) -> str:
        """Obtiene la cadena de conexión."""
        return self._connection_string

# Factory Pattern
class PaymentMethod(ABC):
    """Clase abstracta para métodos de pago."""

    @abstractmethod
    def process_payment(self, amount: float) -> bool:
        """Procesa un pago."""
        pass

class CreditCard(PaymentMethod):
    """Implementación de pago con tarjeta de crédito."""

    def __init__(self, card_number: str) -> None:
        self.card_number = card_number

    def process_payment(self, amount: float) -> bool:
        """Procesa un pago con tarjeta de crédito."""
        if amount <= 0:
            raise ValueError("El monto debe ser positivo")
        print(f"Procesando pago de ${amount} con tarjeta {self.card_number}")
        return True

class PayPal(PaymentMethod):
    """Implementación de pago con PayPal."""

    def __init__(self, email: str) -> None:
        self.email = email

    def process_payment(self, amount: float) -> bool:
        """Procesa un pago con PayPal."""
        if amount <= 0:
            raise ValueError("El monto debe ser positivo")
        print(f"Procesando pago de ${amount} con PayPal ({self.email})")
        return True

class PaymentMethodFactory:
    """Factoría para crear métodos de pago."""

    @staticmethod
    def create_payment_method(method_type: str, **kwargs) -> PaymentMethod:
        """Crea un método de pago según el tipo."""
        if method_type.lower() == "creditcard":
            return CreditCard(kwargs.get("card_number", ""))
        elif method_type.lower() == "paypal":
            return PayPal(kwargs.get("email", ""))
        else:
            raise ValueError(f"Método de pago no soportado: {method_type}")

# Observer Pattern
class Observer(ABC):
    """Interfaz para observadores."""

    @abstractmethod
    def update(self, subject: 'Subject', event: str, data: Any = None) -> None:
        """Actualiza el observador."""
        pass

class Subject:
    """Sujeto observable."""

    def __init__(self) -> None:
        self._observers: List[Observer] = []

    def attach(self, observer: Observer) -> None:
        """Agrega un observador."""
        if observer not in self._observers:
            self._observers.append(observer)

    def detach(self, observer: Observer) -> None:
        """Elimina un observador."""
        if observer in self._observers:
            self._observers.remove(observer)

    def notify(self, event: str, data: Any = None) -> None:
        """Notifica a todos los observadores."""
        for observer in self._observers:
            observer.update(self, event, data)

class OrderObserver(Observer):
    """Observador específico para órdenes."""

    def __init__(self, name: str) -> None:
        self.name = name

    def update(self, subject: Subject, event: str, data: Any = None) -> None:
        """Actualiza cuando hay un evento en la orden."""
        print(f"Observador {self.name}: Evento '{event}' con datos {data}")

# Strategy Pattern
class ShippingStrategy(ABC):
    """Estrategia abstracta para envío."""

    @abstractmethod
    def calculate_shipping(self, weight: float, distance: float) -> float:
        """Calcula el costo de envío."""
        pass

class StandardShipping(ShippingStrategy):
    """Estrategia de envío estándar."""

    def calculate_shipping(self, weight: float, distance: float) -> float:
        """Calcula el costo de envío estándar."""
        return weight * 0.5 + distance * 0.1

class ExpressShipping(ShippingStrategy):
    """Estrategia de envío express."""

    def calculate_shipping(self, weight: float, distance: float) -> float:
        """Calcula el costo de envío express."""
        return weight * 1.0 + distance * 0.3

class ShippingContext:
    """Contexto para usar estrategias de envío."""

    def __init__(self, strategy: ShippingStrategy) -> None:
        self._strategy = strategy

    def set_strategy(self, strategy: ShippingStrategy) -> None:
        """Cambia la estrategia de envío."""
        self._strategy = strategy

    def calculate_shipping(self, weight: float, distance: float) -> float:
        """Calcula el costo de envío usando la estrategia actual."""
        return self._strategy.calculate_shipping(weight, distance)

# Ejemplo de uso completo
def main() -> None:
    """Función principal que demuestra todos los patrones."""

    # Singleton
    print("=== Singleton Pattern ===")
    db1 = DatabaseConnection()
    db2 = DatabaseConnection()
    print(f"Mismas instancias: {db1 is db2}")
    db1.connect()
    print(f"Conectado: {db1.is_connected()}")
    print(f"Cadena de conexión: {db1.get_connection_string()}")

    # Factory
    print("\n=== Factory Pattern ===")
    try:
        credit_card = PaymentMethodFactory.create_payment_method(
            "creditcard", card_number="1234-5678-9012-3456"
        )
        paypal = PaymentMethodFactory.create_payment_method(
            "paypal", email="user@example.com"
        )

        credit_card.process_payment(100.0)
        paypal.process_payment(200.0)

        # Intento con método no soportado
        PaymentMethodFactory.create_payment_method("bitcoin")
    except ValueError as e:
        print(f"Error: {e}")

    # Observer
    print("\n=== Observer Pattern ===")
    subject = Subject()
    observer1 = OrderObserver("Notificaciones")
    observer2 = OrderObserver("Logs")

    subject.attach(observer1)
    subject.attach(observer2)

    subject.notify("ORDER_CREATED", {"order_id": 123, "amount": 100.0})
    subject.notify("ORDER_SHIPPED", {"tracking_number": "TRK123456"})

    # Strategy
    print("\n=== Strategy Pattern ===")
    context = ShippingContext(StandardShipping())
    print(f"Envío estándar: ${context.calculate_shipping(5.0, 10.0)}")

    context.set_strategy(ExpressShipping())
    print(f"Envío express: ${context.calculate_shipping(5.0, 10.0)}")

if __name__ == "__main__":
    main()

