from typing import Optional, List, Any, Iterator
from collections import deque

# Linked List Implementation
class ListNode:
    """Node for singly linked list."""
    def __init__(self, val: int = 0, next: Optional['ListNode'] = None):
        self.val = val
        self.next = next

class LinkedList:
    """
    Singly linked list implementation with common operations.

    Time Complexity:
        - Append: O(n)
        - Prepend: O(1)
        - Search: O(n)
        - Delete: O(n)
        - Access by index: O(n)
    """
    def __init__(self):
        self.head: Optional[ListNode] = None
        self.size: int = 0

    def append(self, val: int) -> None:
        """Add a new node with value at the end."""
        new_node = ListNode(val)
        if not self.head:
            self.head = new_node
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = new_node
        self.size += 1

    def prepend(self, val: int) -> None:
        """Add a new node with value at the beginning."""
        new_node = ListNode(val, self.head)
        self.head = new_node
        self.size += 1

    def search(self, val: int) -> int:
        """
        Search for value and return its index.
        Returns -1 if not found.
        """
        current = self.head
        index = 0
        while current:
            if current.val == val:
                return index
            current = current.next
            index += 1
        return -1

    def delete(self, val: int) -> bool:
        """
        Delete first occurrence of value.
        Returns True if deleted, False otherwise.
        """
        if not self.head:
            return False

        # If head node is to be deleted
        if self.head.val == val:
            self.head = self.head.next
            self.size -= 1
            return True

        current = self.head
        while current.next:
            if current.next.val == val:
                current.next = current.next.next
                self.size -= 1
                return True
            current = current.next
        return False

    def get(self, index: int) -> int:
        """
        Get value at given index.
        Raises IndexError if index is out of bounds.
        """
        if index < 0 or index >= self.size:
            raise IndexError("Index out of bounds")

        current = self.head
        for _ in range(index):
            current = current.next
        return current.val

    def __len__(self) -> int:
        return self.size

    def __iter__(self) -> Iterator[int]:
        """Iterate through all values in the list."""
        current = self.head
        while current:
            yield current.val
            current = current.next

    def __str__(self) -> str:
        return " -> ".join(str(val) for val in self)

